// Relationship compiler tests (HFY-TSK-251, relationship-compiler). Plain node:test:
// `node --test test/records/relationships.node-test.js` needs no network, no AWS and no install. `npm test` runs it
// after vitest. Every fixture is synthetic: placeholder names, ids I9001 and up. The expectations come from
// fixtures/gramps-relationships.golden.json, generated by scripts/records/gen-gramps-relationship-goldens.py under the
// Gramps 6.0.6 bundle shim (the steps Gramps' own editors perform, read back from a Gramps database) and checked
// without Gramps by scripts/records/check_relationship_goldens.py.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  ERROR, MAX_CHILDREN, MAX_TXN_ACTIONS, TXN_COST, WARNING, approvalActionCount, assignSlots, compileRelationship,
} from "../../src/records/relationships.js";
import { findDuplicates, foldName, summarizePerson, unconfirmedDuplicates } from "../../src/records/duplicates.js";
import { applyOps, canonicalJson, validateOps } from "../../src/records/ops.js";
import { checkSemantics } from "../../src/records/semantics.js";

const here = dirname(fileURLToPath(import.meta.url));
const GOLDEN = JSON.parse(readFileSync(resolve(here, "fixtures/gramps-relationships.golden.json"), "utf8"));
const TREE = GOLDEN.tree;
const TODAY = { y: 2026, m: 10, d: 13 };

const H = (cls, n) => `${{ Person: "9a", Family: "9b", Event: "9c", Place: "9d" }[cls]}${String(n).padStart(18, "0")}`;
const P = (n) => `Person:${H("Person", n)}`;
const F = (n) => `Family:${H("Family", n)}`;
const PL = (n) => `Place:${H("Place", n)}`;
const get = (k) => TREE[k];
const mintSeq = () => {
  let n = 0;
  return () => `9f${String(++n).padStart(18, "0")}`;
};
const strip = (o) => {
  const { change, ...rest } = o; // eslint-disable-line no-unused-vars
  return rest;
};
const compile = (intent, extra = {}) => compileRelationship({ intent, get, mint: mintSeq(), today: TODAY, version: () => 7, ...extra });
const codes = (res) => res.errors.map((e) => e.code);
const warnCodes = (res) => res.warnings.map((w) => w.code);

describe("goldens generated by Gramps 6.0.6", () => {
  it("the fixture is the Gramps one", () => {
    assert.equal(GOLDEN.gramps_version, "6.0.6");
    assert.equal(GOLDEN.generator, "scripts/records/gen-gramps-relationship-goldens.py");
    assert.ok(GOLDEN.scenarios.length >= 30);
  });

  // The comparison used for every scenario: created and touched keys, then each object, `change` aside.
  function mismatches(sc, res) {
    const g = sc.gramps;
    const out = [];
    if (canonicalJson(res.preview.created) !== canonicalJson(g.created)) out.push("created");
    if (canonicalJson(res.preview.touched) !== canonicalJson(g.touched)) out.push("touched");
    if (canonicalJson(Object.keys(res.preview.objects).sort()) !== canonicalJson(Object.keys(g.objects).sort())) out.push("object keys");
    for (const k of Object.keys(g.objects)) {
      if (!res.preview.objects[k] || canonicalJson(strip(res.preview.objects[k])) !== canonicalJson(g.objects[k])) out.push(k);
    }
    return out;
  }

  for (const sc of GOLDEN.scenarios) {
    it(`${sc.id}: ${sc.title}`, () => {
      const res = compile(sc.intent);
      assert.equal(res.ok, true, JSON.stringify(res.errors));
      if (sc.tags.includes("already-recorded")) {
        assert.equal(res.alreadyRecorded, true);
        assert.deepEqual(res.ops, []);
        assert.deepEqual(sc.gramps.created.concat(sc.gramps.touched), []);
        return;
      }
      assert.equal(res.alreadyRecorded, false);
      assert.deepEqual(mismatches(sc, res), []);
    });
  }

  it("the comparison itself catches a difference (the check is not vacuous)", () => {
    const sc = GOLDEN.scenarios.find((s) => s.id === "parents-008");
    const res = compile(sc.intent);
    assert.deepEqual(mismatches(sc, res), []);
    const bent = JSON.parse(JSON.stringify(res));
    const fam = bent.preview.created.find((k) => k.startsWith("Family"));
    [bent.preview.objects[fam].father_handle, bent.preview.objects[fam].mother_handle] = [bent.preview.objects[fam].mother_handle, bent.preview.objects[fam].father_handle];
    assert.deepEqual(mismatches(sc, bent), [fam]);
  });

  it("every compiled output passes the two-sided link and cycle validators, run again here on the stored objects", () => {
    for (const sc of GOLDEN.scenarios) {
      const res = compile(sc.intent);
      assert.equal(res.ok, true, sc.id);
      if (res.alreadyRecorded) continue;
      assert.equal(validateOps(res.ops).length, 0, `${sc.id} ops are well formed`);
      const before = Object.fromEntries(res.preview.touched.map((k) => [k, TREE[k]]));
      const applied = applyOps(before, res.ops, { mint: mintSeq() });
      assert.equal(applied.ok, true, sc.id);
      const after = Object.fromEntries([...res.preview.touched, ...res.preview.created].map((k) => [k, applied.objects[k]]));
      const sem = checkSemantics({ before, after, get, today: TODAY });
      assert.deepEqual(sem.errors, [], sc.id);
      assert.equal(sem.ok, true, sc.id);
      assert.equal(canonicalJson(after), canonicalJson(res.preview.objects), `${sc.id}: the ops reproduce the preview`);
    }
  });
});

describe("slots", () => {
  const p = (gender) => ({ gender });
  it("male to the father slot, female to the mother slot, whichever was chosen first", () => {
    const m = p(1);
    const f = p(0);
    assert.deepEqual(assignSlots(m, f), { father: m, mother: f });
    assert.deepEqual(assignSlots(f, m), { father: m, mother: f });
  });

  it("otherwise the first chosen is partner1 (father_handle) and the second partner2 (mother_handle)", () => {
    const a = p(1);
    const b = p(1);
    assert.deepEqual(assignSlots(a, b), { father: a, mother: b });
    assert.deepEqual(assignSlots(b, a), { father: b, mother: a });
    const u = p(2);
    const w = p(2);
    assert.deepEqual(assignSlots(u, w), { father: u, mother: w });
    const x = p(0);
    const y = p(0);
    assert.deepEqual(assignSlots(x, y), { father: x, mother: y });
  });

  it("a person of unknown gender takes the slot the man or the woman leaves", () => {
    const u = p(2);
    assert.deepEqual(assignSlots(u, p(0)).father, u);
    assert.deepEqual(assignSlots(p(1), u).mother, u);
    const m = p(1);
    assert.deepEqual(assignSlots(u, m), { father: m, mother: u });
  });

  it("a lone parent: a woman is the mother, anyone else the father", () => {
    const f = p(0);
    assert.deepEqual(assignSlots(f), { father: null, mother: f });
    const m = p(1);
    assert.deepEqual(assignSlots(m), { father: m, mother: null });
    const u = p(2);
    assert.deepEqual(assignSlots(u), { father: u, mother: null });
  });
});

describe("parents", () => {
  const intent = (parents, person = 9012) => ({ type: "parents", person: P(person), parents });
  const par = (key, rel) => ({ who: { ref: key }, ...(rel ? { rel } : {}) });

  it("reuses a two-parent family, and says so in plain words", () => {
    const res = compile(intent([par(P(9002)), par(P(9001))]));
    assert.deepEqual(res.ops.map((o) => [o.op, o.obj, o.path]), [
      ["add", F(9001), "/child_ref_list"],
      ["add", P(9012), "/parent_family_list"],
    ]);
    assert.deepEqual(res.warnings, []);
    assert.equal(res.stats.created, 0);
    assert.equal(res.summary.length, 1);
    assert.match(res.summary[0].text, /^adds Max Zeta as a child of Bob Alpha and Ann Alpha$/);
    assert.deepEqual(res.summary[0].opIds, ["o1", "o2"]);
    assert.deepEqual(res.base_versions, { [F(9001)]: 7, [P(9012)]: 7 });
    assert.equal(res.subject, P(9012));
  });

  it("one chosen parent with a childless single-parent family reuses it (nothing is created)", () => {
    const res = compile(intent([par(P(9005))]));
    assert.equal(res.stats.created, 0);
    assert.deepEqual(res.ops.map((o) => o.obj), [F(9002), P(9012)]);
    assert.deepEqual(res.warnings, []);
  });

  it("two chosen parents fill the empty slot of a single-parent family that has no children", () => {
    const res = compile(intent([par(P(9005)), par(P(9009))]));
    assert.equal(res.stats.created, 0);
    const set = res.ops.find((o) => o.op === "set");
    assert.deepEqual({ obj: set.obj, path: set.path, base: set.base, value: set.value }, { obj: F(9002), path: "/mother_handle", base: null, value: H("Person", 9009) });
    assert.ok(res.ops.some((o) => o.obj === P(9009) && o.path === "/family_list" && o.value === H("Family", 9002)));
    assert.deepEqual(res.warnings, []);
  });

  it("never fills the empty slot of a single-parent family that has other children: a new family and a warning", () => {
    const res = compile(intent([par(P(9006)), par(P(9008))]));
    assert.deepEqual(warnCodes(res), [WARNING.singleParentFamilyHasChildren]);
    assert.equal(res.warnings[0].family, F(9003));
    assert.match(res.warnings[0].detail, /consider merging/);
    assert.equal(res.stats.created, 1);
    assert.ok(!res.ops.some((o) => o.obj === F(9003)), "the family with children is not touched");
    assert.ok(res.preview.created[0].startsWith("Family:"));
    // Fay's families: the old one first, the new one appended
    const fay = res.preview.objects[P(9006)];
    assert.deepEqual(fay.family_list, [H("Family", 9003), res.preview.created[0].slice(7)]);
  });

  it("a new family is appended after the existing parent families, so the main parents stay main", () => {
    const res = compile(intent([par(P(9008)), par(P(9009))], 9004));
    const dee = res.preview.objects[P(9004)];
    assert.equal(dee.parent_family_list.length, 2);
    assert.equal(dee.parent_family_list[0], H("Family", 9001));
    assert.equal(dee.parent_family_list[1], res.preview.created[0].slice(7));
    assert.deepEqual(warnCodes(res), [WARNING.childHasBirthParents]);
    // adopted parents do not raise it
    const adopted = compile(intent([par(P(9008), "adopted"), par(P(9009), "adopted")], 9004));
    assert.deepEqual(warnCodes(adopted), []);
  });

  it("a parent under 13 years older than the child is a warning, not an error", () => {
    const res = compile(intent([par(P(9014))]));
    assert.equal(res.ok, true);
    assert.deepEqual(warnCodes(res), [WARNING.parentTooYoung]);
    assert.equal(res.warnings[0].years, 10);
  });

  it("an already recorded parent set changes nothing", () => {
    const res = compile(intent([par(P(9002)), par(P(9001))], 9003));
    assert.equal(res.alreadyRecorded, true);
    assert.deepEqual(res.ops, []);
    assert.deepEqual(res.base_versions, {});
  });

  it("repairs a half-recorded link rather than calling it done", () => {
    const tree = JSON.parse(JSON.stringify(TREE));
    tree[F(9001)].child_ref_list.push({ ...tree[F(9001)].child_ref_list[0], ref: H("Person", 9012) }); // the family lists Max, Max does not list the family
    const res = compileRelationship({ intent: intent([par(P(9002)), par(P(9001))]), get: (k) => tree[k], mint: mintSeq(), today: TODAY });
    assert.equal(res.ok, true);
    assert.deepEqual(res.ops.map((o) => [o.op, o.obj, o.path]), [["add", P(9012), "/parent_family_list"]]);
  });

  it("refuses a parent who is the person, the same parent twice, and a count other than one or two", () => {
    for (const parents of [[par(P(9012))], [par(P(9001)), par(P(9001))], [], [par(P(9001)), par(P(9002)), par(P(9005))]]) {
      const res = compile(intent(parents));
      assert.equal(res.ok, false);
      assert.deepEqual(codes(res), [ERROR.badIntent]);
    }
  });

  it("an unknown person or a wrong class is refused", () => {
    assert.deepEqual(codes(compile(intent([par("Person:nobody")]))), [ERROR.unknownObject]);
    assert.deepEqual(codes(compile(intent([par(F(9001))]))), [ERROR.badIntent]);
    assert.deepEqual(codes(compile({ type: "parents", person: "Person:nobody", parents: [par(P(9001))] })), [ERROR.unknownObject]);
  });

  it("a relation word that is not one of the eight is refused", () => {
    assert.deepEqual(codes(compile(intent([par(P(9001), "godparent")]))), [ERROR.badIntent]);
  });

  it("the ChildRef relations follow the slots, not the order chosen", () => {
    const res = compile(intent([par(P(9001), "adopted"), par(P(9002), "foster")]));
    const ref = res.ops.find((o) => o.path === "/child_ref_list").value;
    assert.equal(ref.frel.value, 5, "Bob is the father slot: foster");
    assert.equal(ref.mrel.value, 2, "Ann is the mother slot: adopted");
  });
});

describe("cycles", () => {
  it("an intent that would make someone their own ancestor fails with cycle (a child as parent)", () => {
    const res = compile({ type: "parents", person: P(9002), parents: [{ who: { ref: P(9003) } }] });
    assert.equal(res.ok, false);
    assert.deepEqual(codes(res), [ERROR.cycle]);
    assert.ok(res.errors[0].cycle.includes(P(9002)) && res.errors[0].cycle.includes(P(9003)));
    assert.deepEqual(res.ops, undefined);
  });

  it("the same through the children intent", () => {
    const res = compile({ type: "children", person: P(9003), otherParent: { unknown: true }, children: [{ who: { ref: P(9002) } }] });
    assert.deepEqual(codes(res), [ERROR.cycle]);
  });

  it("a longer loop: a grandchild as a parent of the grandparent", () => {
    const tree = JSON.parse(JSON.stringify(TREE));
    // Cal (9003) has a child Gus-like grandchild: make Max (9012) a child of Cal through a new family
    const fam = JSON.parse(JSON.stringify(tree[F(9002)]));
    fam.handle = "9bgrand";
    fam.father_handle = H("Person", 9003);
    fam.child_ref_list = [{ ...tree[F(9001)].child_ref_list[0], ref: H("Person", 9012) }];
    tree["Family:9bgrand"] = fam;
    tree[P(9003)].family_list.push("9bgrand");
    tree[P(9012)].parent_family_list.push("9bgrand");
    const res = compileRelationship({ intent: { type: "parents", person: P(9002), parents: [{ who: { ref: P(9012) } }] }, get: (k) => tree[k], mint: mintSeq(), today: TODAY });
    assert.deepEqual(codes(res), [ERROR.cycle]);
  });

  it("a parent cannot be their own child", () => {
    const res = compile({ type: "children", person: P(9008), otherParent: { unknown: true }, children: [{ who: { ref: P(9008) } }] });
    assert.deepEqual(codes(res), [ERROR.badIntent]);
  });
});

describe("children", () => {
  const kid = (who, extra = {}) => ({ who, ...extra });
  const intent = (person, otherParent, children) => ({ type: "children", person: P(person), otherParent, children });

  it("an unknown other parent: the person's single-parent family, or a new one", () => {
    const reuse = compile(intent(9006, { unknown: true }, [kid({ ref: P(9012) })]));
    assert.equal(reuse.stats.created, 0);
    assert.deepEqual(reuse.ops.map((o) => o.obj), [F(9003), P(9012)]);
    const fresh = compile(intent(9008, { unknown: true }, [kid({ ref: P(9012) })]));
    assert.equal(fresh.stats.created, 1);
    assert.equal(fresh.ops[0].op, "create");
    assert.equal(fresh.ops[0].value.father_handle, H("Person", 9008));
    assert.equal(fresh.ops[0].value.mother_handle, null);
  });

  it("no otherParent at all means unknown", () => {
    const res = compile({ type: "children", person: P(9008), children: [kid({ ref: P(9012) })] });
    assert.equal(res.ok, true);
    assert.equal(res.stats.created, 1);
  });

  it("the relation to me and to the other parent land on their own slots", () => {
    const res = compile(intent(9008, { ref: P(9009) }, [kid({ ref: P(9012) }, { relToMe: "adopted", relToOther: "foster" })]));
    const fam = res.ops[0].value;
    assert.equal(fam.child_ref_list[0].frel.value, 2, "Hal is the father slot");
    assert.equal(fam.child_ref_list[0].mrel.value, 5, "Ida is the mother slot");
  });

  it("a child already in the family is skipped; all of them already there is already recorded", () => {
    const some = compile(intent(9002, { ref: P(9001) }, [kid({ ref: P(9003) }), kid({ ref: P(9012) })]));
    assert.deepEqual(some.ops.map((o) => o.obj), [F(9001), P(9012)]);
    assert.equal(some.summary.length, 1);
    const all = compile(intent(9002, { ref: P(9001) }, [kid({ ref: P(9003) }), kid({ ref: P(9004) })]));
    assert.equal(all.alreadyRecorded, true);
  });

  it("more than 10 children fails with too_many_children; 10 is fine", () => {
    const kids = (n) => Array.from({ length: n }, (_, i) => kid({ new: { given: `Kid${i}`, surname: "Zz", gender: "female", birthYear: 2000 + (i % 20) } }));
    const over = compile(intent(9008, { unknown: true }, kids(MAX_CHILDREN + 1)));
    assert.equal(over.ok, false);
    assert.deepEqual(codes(over), [ERROR.tooManyChildren]);
    assert.equal(over.errors[0].limit, 10);
    assert.equal(compile(intent(9008, { unknown: true }, kids(MAX_CHILDREN))).ok, true);
    assert.deepEqual(codes(compile(intent(9008, { unknown: true }, []))), [ERROR.badIntent]);
  });

  it("an approval transaction of more than 100 actions fails with proposal_too_large", () => {
    const stubKids = Array.from({ length: 10 }, (_, i) => kid({ new: { given: `Kid${i}`, surname: "Zz", gender: "male", birthYear: 1990 + i } }));
    const withStubOther = compile(intent(9008, { new: { given: "Other", surname: "Zz", gender: "female", birthYear: 1966 } }, stubKids));
    assert.equal(withStubOther.ok, false);
    assert.deepEqual(codes(withStubOther), [ERROR.proposalTooLarge]);
    assert.equal(withStubOther.errors[0].limit, MAX_TXN_ACTIONS);
    assert.ok(withStubOther.errors[0].actions > 100);
    // the same ten children with the other parent unknown fit
    const fits = compile(intent(9008, { unknown: true }, stubKids));
    assert.equal(fits.ok, true);
    assert.equal(fits.stats.actions, approvalActionCount({ touched: fits.stats.touched, created: fits.stats.created }));
    assert.ok(fits.stats.actions <= 100);
    // the budget is a parameter
    const tight = compile(intent(9008, { unknown: true }, stubKids), { maxActions: fits.stats.actions - 1 });
    assert.deepEqual(codes(tight), [ERROR.proposalTooLarge]);
    assert.equal(compile(intent(9008, { unknown: true }, stubKids), { maxActions: fits.stats.actions }).ok, true);
  });

  it("counts the approval transaction: batch, objects, ids minted, proposal copies", () => {
    assert.equal(approvalActionCount({ touched: 2, created: 3 }), TXN_COST.batchFixed + 2 * 5 + 3 + TXN_COST.proposalFixed + 5);
    assert.equal(approvalActionCount({ touched: 0, created: 0 }), 6);
    assert.equal(approvalActionCount({ touched: 1, created: 1, extra: 4 }), 6 + 6 + 1 + 4);
    const res = compile({ type: "spouse", person: P(9008), spouse: { ref: P(9009) }, relType: "married", married: { year: 1990 }, ended: { how: "divorced", year: 2001 } });
    assert.equal(res.stats.actions, 24);
    assert.deepEqual({ touched: res.stats.touched, created: res.stats.created, ops: res.stats.ops }, { touched: 2, created: 3, ops: 5 });
  });

  it("warns when a child already has birth parents", () => {
    const res = compile(intent(9008, { unknown: true }, [kid({ ref: P(9003) })]));
    assert.deepEqual(warnCodes(res), [WARNING.childHasBirthParents]);
    assert.equal(res.warnings[0].person, P(9003));
  });
});

describe("spouse", () => {
  const intent = (extra) => ({ type: "spouse", person: P(9008), spouse: { ref: P(9009) }, relType: "married", ...extra });

  it("married then divorced: a family, a Marriage event and a Divorce event, role Family", () => {
    const res = compile(intent({ married: { year: 1990 }, ended: { how: "divorced", year: 2001 } }));
    assert.deepEqual(res.ops.slice(0, 3).map((o) => [o.op, o.cls, o.obj]), [["create", "Event", "new:1"], ["create", "Event", "new:2"], ["create", "Family", "new:3"]]);
    const fam = res.ops[2].value;
    assert.deepEqual(fam.event_ref_list.map((r) => [r.ref, r.role.value]), [["new:1", 8], ["new:2", 8]]);
    assert.equal(res.ops[0].value.type.value, 1);
    assert.equal(res.ops[1].value.type.value, 7);
    assert.deepEqual(res.ops[0].value.date.dateval, [0, 0, 1990, false]);
    assert.equal(fam.type.value, 0);
    assert.deepEqual(res.summary.map((s) => s.text), ["records the marriage of Hal Delta and Ida Delta in 1990", "records the divorce of Hal Delta and Ida Delta in 2001", "makes a new family for Hal Delta and Ida Delta (married)"]);
  });

  it("an existing family of the pair is reused and its type updated", () => {
    const res = compile({ type: "spouse", person: P(9002), spouse: { ref: P(9001) }, relType: "civil_union" });
    assert.deepEqual(res.ops.map((o) => [o.op, o.obj, o.path]), [["set", F(9001), "/type"]]);
    assert.deepEqual(res.ops[0].base, TREE[F(9001)].type);
    assert.equal(res.ops[0].value.value, 2);
  });

  it("a marriage the family already has is left alone, with a warning", () => {
    const res = compile({ type: "spouse", person: P(9002), spouse: { ref: P(9001) }, relType: "married", married: { year: 1980 } });
    assert.equal(res.alreadyRecorded, true);
    assert.deepEqual(warnCodes(res), [WARNING.marriageAlreadyRecorded]);
  });

  it("a new family for a pair adds a Marriage event to an existing family that has none", () => {
    const tree = JSON.parse(JSON.stringify(TREE));
    tree[F(9001)].event_ref_list = [];
    const res = compileRelationship({ intent: { type: "spouse", person: P(9002), spouse: { ref: P(9001) }, relType: "married", married: { year: 1975 } }, get: (k) => tree[k], mint: mintSeq(), today: TODAY });
    assert.deepEqual(res.ops.map((o) => [o.op, o.obj, o.path || ""]), [["create", "new:1", ""], ["add", F(9001), "/event_ref_list"]]);
  });

  it("widowed: no Divorce event, and an offer to add the death year when none is recorded", () => {
    const res = compile(intent({ married: { year: 1985 }, ended: { how: "widowed", year: 1999 } }));
    assert.deepEqual(res.ops.filter((o) => o.op === "create").map((o) => `${o.cls}:${o.value.type.value}`), ["Event:1", "Family:0"]);
    assert.deepEqual(res.followUps.map((f) => [f.code, f.person]), [["offer_death_year", P(9009)]]);
  });

  it("a new place is created and enclosed; a place that exists is only referenced", () => {
    const mk = (place) => compile(intent({ married: { year: 1991, place } }));
    const fresh = mk({ new: { name: "Sampleville", type: "City", enclosedBy: PL(9002) } });
    assert.deepEqual(fresh.ops.filter((o) => o.op === "create").map((o) => o.cls), ["Place", "Event", "Family"]);
    assert.equal(fresh.ops[1].value.place, "new:1");
    const known = mk({ ref: PL(9002) });
    assert.equal(known.ops[0].value.place, H("Place", 9002));
    assert.deepEqual(known.ops.filter((o) => o.op === "create").map((o) => o.cls), ["Event", "Family"]);
  });

  it("a street, a building or a number is not a place a member can add", () => {
    for (const type of ["Street", "Building", "Number", "Nonsense"]) {
      const res = compile(intent({ married: { year: 1991, place: { new: { name: "Somewhere", type } } } }));
      assert.deepEqual(codes(res), [ERROR.badIntent], type);
    }
    assert.deepEqual(codes(compile(intent({ married: { year: 1991, place: { ref: P(9001) } } }))), [ERROR.badIntent]);
    assert.deepEqual(codes(compile(intent({ married: { year: 1991, place: { ref: "Place:nowhere" } } }))), [ERROR.unknownObject]);
  });

  it("a person cannot be their own spouse; a kind of partnership and an ending are checked", () => {
    assert.deepEqual(codes(compile({ ...intent({}), spouse: { ref: P(9008) } })), [ERROR.badIntent]);
    assert.deepEqual(codes(compile(intent({ relType: "engaged" }))), [ERROR.badIntent]);
    assert.deepEqual(codes(compile(intent({ ended: { how: "annulled" } }))), [ERROR.badIntent]);
    assert.deepEqual(codes(compile(intent({ married: { year: "1990" } }))), [ERROR.badIntent]);
  });

  it("a divorce with no year still records a Divorce event, with no date", () => {
    const res = compile(intent({ ended: { how: "divorced" } }));
    const divorce = res.ops.find((o) => o.op === "create" && o.value.type && o.value.type.value === 7);
    assert.deepEqual(divorce.value.date.dateval, [0, 0, 0, false]);
  });
});

describe("unlink", () => {
  it("a child: removes the ChildRef and the parent_family_list entry; destructive", () => {
    const res = compile({ type: "unlink", family: F(9001), person: P(9003), as: "child" });
    assert.equal(res.destructive, true);
    assert.deepEqual(res.ops.map((o) => [o.op, o.obj, o.path]), [
      ["remove", F(9001), `/child_ref_list/@ref=${H("Person", 9003)}`],
      ["remove", P(9003), `/parent_family_list/@=${H("Family", 9001)}`],
    ]);
    assert.match(res.summary[0].text, /^removes Cal Alpha as a child of the family of Bob Alpha and Ann Alpha$/);
  });

  it("a partner: clears the slot and removes the family from the person", () => {
    const res = compile({ type: "unlink", family: F(9001), person: P(9001), as: "partner" });
    assert.deepEqual(res.ops.map((o) => [o.op, o.path]), [["set", "/mother_handle"], ["remove", `/family_list/@=${H("Family", 9001)}`]]);
    assert.equal(res.ops[0].base, H("Person", 9001));
    assert.equal(res.ops[0].value, null);
    assert.deepEqual(res.warnings, []);
  });

  it("the last partner leaves a family with no parents: a warning", () => {
    const res = compile({ type: "unlink", family: F(9002), person: P(9005), as: "partner" });
    assert.deepEqual(warnCodes(res), [WARNING.familyHasNoParents]);
    assert.equal(res.warnings[0].children, 0);
  });

  it("someone who is not linked is already unlinked", () => {
    const res = compile({ type: "unlink", family: F(9001), person: P(9012), as: "child" });
    assert.equal(res.alreadyRecorded, true);
    assert.equal(res.destructive, true);
  });

  it("the ops it makes apply, and a stale view is a conflict, not a silent overwrite", () => {
    const res = compile({ type: "unlink", family: F(9001), person: P(9003), as: "child" });
    const moved = JSON.parse(JSON.stringify(TREE));
    moved[F(9001)].child_ref_list[0].frel.value = 2; // the ChildRef changed since the proposal was made
    const r = applyOps({ [F(9001)]: moved[F(9001)], [P(9003)]: moved[P(9003)] }, res.ops);
    assert.equal(r.ok, false);
    assert.equal(r.conflicts[0].reason, "content_changed");
  });

  it("as must be child or partner", () => {
    assert.deepEqual(codes(compile({ type: "unlink", family: F(9001), person: P(9003), as: "sibling" })), [ERROR.badIntent]);
    assert.deepEqual(codes(compile({ type: "unlink", family: P(9001), person: P(9003), as: "child" })), [ERROR.badIntent]);
  });
});

describe("stubs", () => {
  const stubIntent = (stub) => ({ type: "parents", person: P(9012), parents: [{ who: { new: stub } }] });

  it("a stub is a Birth Name primary name, a year-only Birth event and an empty gramps_id", () => {
    const res = compile(stubIntent({ given: "Stubfirst", surname: "Stublast", gender: "female", birthYear: 1950, living: "yes" }));
    const person = res.ops.find((o) => o.op === "create" && o.cls === "Person").value;
    assert.equal(person.gramps_id, "");
    assert.equal(person.primary_name.type.value, 2);
    assert.equal(person.primary_name.surname_list[0].primary, true);
    assert.equal(person.gender, 0);
    assert.equal(person.birth_ref_index, 0);
    assert.equal(person.death_ref_index, -1);
    const birth = res.ops.find((o) => o.op === "create" && o.cls === "Event").value;
    assert.deepEqual(birth.date.dateval, [0, 0, 1950, false]);
    assert.equal(birth.date.sortval, 2433283);
    assert.equal(birth.type.value, 12);
    for (const o of res.ops.filter((x) => x.op === "create")) assert.equal(o.value.gramps_id, "", `${o.cls} has no id yet`);
  });

  it("a Death event only when living is no and a year was given; no Birth event without a year", () => {
    const count = (stub) => compile(stubIntent(stub)).ops.filter((o) => o.op === "create" && o.cls === "Event").map((o) => o.value.type.value);
    assert.deepEqual(count({ given: "A", surname: "B", birthYear: 1950, living: "no", deathYear: 2010 }), [12, 13]);
    assert.deepEqual(count({ given: "A", surname: "B", birthYear: 1950, living: "no" }), [12]);
    assert.deepEqual(count({ given: "A", surname: "B", birthYear: 1950, living: "yes", deathYear: 2010 }), [12]);
    assert.deepEqual(count({ given: "A", surname: "B", living: "no", deathYear: 2010 }), [13]);
    assert.deepEqual(count({ given: "A", surname: "B" }), []);
    const onlyDeath = compile(stubIntent({ given: "A", surname: "B", living: "no", deathYear: 2010 })).ops.find((o) => o.cls === "Person").value;
    assert.deepEqual([onlyDeath.birth_ref_index, onlyDeath.death_ref_index], [-1, 0]);
  });

  it("numbers the stubs first (what duplicates and confirmDistinct name), then their events, then the family", () => {
    const res = compile({
      type: "parents", person: P(9012),
      parents: [{ who: { new: { given: "A", surname: "S", gender: "male", birthYear: 1950 } } }, { who: { new: { given: "B", surname: "S", gender: "female", birthYear: 1952 } } }],
    });
    assert.deepEqual(res.ops.filter((o) => o.op === "create").map((o) => `${o.obj}:${o.cls}`), ["new:1:Person", "new:2:Person", "new:3:Event", "new:4:Event", "new:5:Family"]);
    const fam = res.ops[4].value;
    assert.deepEqual([fam.father_handle, fam.mother_handle], ["new:1", "new:2"]);
  });

  it("the returned ops keep new:n and do not depend on the handles the validation pass minted", () => {
    const a = compile(stubIntent({ given: "A", surname: "B", gender: "male", birthYear: 1950 }), { mint: mintSeq() });
    const b = compileRelationship({ intent: stubIntent({ given: "A", surname: "B", gender: "male", birthYear: 1950 }), get, today: TODAY });
    assert.deepEqual(a.ops, b.ops);
    assert.ok(!JSON.stringify(a.ops).includes("9f0000"));
  });

  it("refuses a stub with no name, a bad gender or living, a fractional year", () => {
    for (const stub of [{}, { given: " ", surname: "" }, { given: "A", gender: "robot" }, { given: "A", living: "maybe" }, { given: "A", birthYear: 1950.5 }, { given: "A".repeat(101) }]) {
      const res = compile(stubIntent(stub));
      assert.equal(res.ok, false, JSON.stringify(stub));
      assert.deepEqual(codes(res), [ERROR.badStub]);
    }
  });

  it("the error never echoes what was typed", () => {
    const res = compile(stubIntent({ given: "Typedname".repeat(20), gender: "robot" }));
    assert.ok(!JSON.stringify(res).includes("Typedname"));
  });

  it("a date the Gramps rules refuse is an error on the new:n object (a member cannot enter a year before 1000 or in the future)", () => {
    const early = compile(stubIntent({ given: "A", surname: "B", birthYear: 999 }));
    assert.equal(early.ok, false);
    assert.deepEqual(early.errors.map((e) => [e.code, e.obj]), [["year_out_of_range", "new:2"]]);
    assert.equal(compile(stubIntent({ given: "A", surname: "B", birthYear: 999 }), { admin: true }).ok, true);
    const future = compile(stubIntent({ given: "A", surname: "B", birthYear: 2027 }));
    assert.deepEqual(codes(future), ["date_in_future"]);
  });

  it("normalizes names to NFC and trims", () => {
    const res = compile(stubIntent({ given: "  Zoë  ", surname: "Muller" }));
    assert.equal(res.ops.find((o) => o.cls === "Person").value.primary_name.first_name, "Zoë");
  });
});

describe("the duplicate matcher", () => {
  const people = [
    { handle: "h1", names: [{ given: "Zoë", surname: "Müller" }], gender: 0, birthYear: 1950, deathYear: 2012 },
    { handle: "h2", names: [{ given: "Thomas", surname: "Smith" }], gender: 1, birthYear: 1948 },
    { handle: "h3", names: [{ given: "Johanna", surname: "Brown" }, { given: "Johanna", surname: "Green" }], gender: 0, birthYear: null },
    { handle: "h4", names: [{ given: "Zoe", surname: "Muller" }], gender: 0, birthYear: 1990 },
    { handle: "h5", names: [{ given: "Anton", surname: "Weber" }], gender: 1 },
  ];
  const ids = (dups, i = 0) => (dups[i] ? dups[i].candidates.map((c) => c.handle) : []);

  it("folds case and accents", () => {
    assert.equal(foldName("  ZOË  Müller-Ünal "), "zoe muller unal");
    assert.equal(foldName("Straße"), "strasse");
    assert.equal(foldName("Øster"), "oster");
    assert.equal(foldName(null), "");
  });

  it("returns candidates for a synthetic near-duplicate name", () => {
    const dups = findDuplicates([{ for: "new:1", stub: { given: "ZOE", surname: "muller", gender: "female", birthYear: 1951 } }], people);
    assert.equal(dups.length, 1);
    assert.equal(dups[0].for, "new:1");
    assert.deepEqual(ids(dups), ["h1"], "h4 was born 40 years later");
    assert.deepEqual(dups[0].candidates[0], { handle: "h1", displayName: "Zoë Müller", lifespan: "1950-2012" });
  });

  it("forgives a one-letter slip, a nickname or initial, and a compound surname", () => {
    assert.deepEqual(ids(findDuplicates([{ given: "Thomass", surname: "Smyth", gender: "male" }], people)), ["h2"]);
    assert.deepEqual(ids(findDuplicates([{ given: "Tom", surname: "Smith" }], people)), [], "Tom is not a prefix of Thomas");
    assert.deepEqual(ids(findDuplicates([{ given: "Joh", surname: "Brown" }], people)), ["h3"]);
    assert.deepEqual(ids(findDuplicates([{ given: "J", surname: "Brown" }], people)), ["h3"], "an initial");
  });

  it("reads an alternate (married) name as well as the primary one, and shows the primary", () => {
    const dups = findDuplicates([{ given: "Johanna", surname: "Green" }], people);
    assert.deepEqual(dups[0].candidates, [{ handle: "h3", displayName: "Johanna Brown", lifespan: "" }]);
  });

  it("does not match a different person: other name, other gender, birth years far apart", () => {
    assert.deepEqual(findDuplicates([{ given: "Anna", surname: "Weber", gender: "female" }], people), []);
    assert.deepEqual(findDuplicates([{ given: "Anton", surname: "Weber", gender: "female" }], people), []);
    assert.deepEqual(findDuplicates([{ given: "Zoe", surname: "Muller", birthYear: 1900 }], people), []);
    assert.equal(findDuplicates([{ given: "Anton", surname: "Weber", gender: "male" }], people).length, 1);
    assert.deepEqual(findDuplicates([{ given: "Zoe", surname: "Muller", gender: "male" }], people), [], "a known and different gender is not the same person");
  });

  it("ranks the better match first, caps the list, and skips the people the request already names", () => {
    const many = Array.from({ length: 8 }, (_, i) => ({ handle: `m${i}`, names: [{ given: "Rita", surname: "Rossi" }], gender: 0, birthYear: 1960 + (i % 2) }));
    const dups = findDuplicates([{ given: "Rita", surname: "Rossi", birthYear: 1960 }], [...many, { handle: "x", names: [{ given: "Rita", surname: "Rossa" }], gender: 0 }], { limit: 3 });
    assert.equal(dups[0].candidates.length, 3);
    assert.ok(dups[0].candidates.every((c) => ["m0", "m2", "m4", "m6"].includes(c.handle)), "same birth year ranks first");
    assert.deepEqual(ids(findDuplicates([{ given: "Rita", surname: "Rossi" }], many, { exclude: many.map((m) => m.handle) })), []);
  });

  it("a plain array of stubs is numbered new:1, new:2", () => {
    const dups = findDuplicates([{ given: "Nobody", surname: "Here" }, { given: "Anton", surname: "Weber" }], people);
    assert.deepEqual(dups.map((d) => d.for), ["new:2"]);
  });

  it("a candidate carries a handle, a name and a lifespan, nothing else", () => {
    const dups = findDuplicates([{ given: "Zoe", surname: "Muller" }], people);
    for (const c of dups[0].candidates) assert.deepEqual(Object.keys(c).sort(), ["displayName", "handle", "lifespan"]);
  });

  it("unconfirmedDuplicates lists the new:n that were not confirmed distinct", () => {
    const dups = [{ for: "new:1", candidates: [{}] }, { for: "new:3", candidates: [{}] }];
    assert.deepEqual(unconfirmedDuplicates(dups, []), ["new:1", "new:3"]);
    assert.deepEqual(unconfirmedDuplicates(dups, ["new:1"]), ["new:3"]);
    assert.deepEqual(unconfirmedDuplicates(dups, ["new:1", "new:3"]), []);
    assert.deepEqual(unconfirmedDuplicates(dups, undefined), ["new:1", "new:3"]);
  });

  it("summarizePerson reads a Gramps Person: the primary and alternate names, the birth and death years", () => {
    const sum = summarizePerson(TREE[P(9001)], (h) => TREE[`Event:${h}`]);
    assert.deepEqual({ handle: sum.handle, names: sum.names, birthYear: sum.birthYear, deathYear: sum.deathYear }, { handle: H("Person", 9001), names: [{ given: "Ann", surname: "Alpha" }], birthYear: 1950, deathYear: null });
    assert.equal(summarizePerson(TREE[P(9001)]).birthYear, null);
  });

  it("through the compiler: duplicates are reported on a preview and block a submit until confirmed", () => {
    const intent = { type: "parents", person: P(9012), parents: [{ who: { new: { given: "Ann", surname: "Alpha", gender: "female", birthYear: 1950 } } }] };
    const people2 = Object.keys(TREE).filter((k) => k.startsWith("Person:")).map((k) => summarizePerson(TREE[k], (h) => TREE[`Event:${h}`]));
    const preview = compile(intent, { people: people2 });
    assert.equal(preview.ok, true);
    assert.deepEqual(preview.duplicates.map((d) => [d.for, d.candidates[0].handle]), [["new:1", H("Person", 9001)]]);
    const blocked = compile(intent, { people: people2, confirmDistinct: [] });
    assert.deepEqual(codes(blocked), [ERROR.unconfirmedDuplicate]);
    assert.deepEqual(blocked.errors[0].unconfirmed, ["new:1"]);
    const confirmed = compile(intent, { people: people2, confirmDistinct: ["new:1"] });
    assert.equal(confirmed.ok, true);
    assert.equal(confirmed.duplicates.length, 1);
    const none = compile(intent);
    assert.deepEqual(none.duplicates, []);
  });

  it("the people the intent names are never offered as a duplicate of its own stub", () => {
    const intent = { type: "parents", person: P(9012), parents: [{ who: { ref: P(9001) } }, { who: { new: { given: "Ann", surname: "Alpha", gender: "female" } } }] };
    const people2 = Object.keys(TREE).filter((k) => k.startsWith("Person:")).map((k) => summarizePerson(TREE[k]));
    assert.deepEqual(compile(intent, { people: people2 }).duplicates, []);
  });
});

describe("the result", () => {
  it("fails closed: a compile that cannot be checked returns no ops", () => {
    const res = compile({ type: "weird" });
    assert.equal(res.ok, false);
    assert.equal(res.ops, undefined);
    assert.deepEqual(codes(compile(null)), [ERROR.badIntent]);
    assert.throws(() => compileRelationship({ intent: { type: "parents" } }), TypeError);
  });

  it("ids every op o1, o2, ... and ties each summary line to its ops", () => {
    const res = compile({ type: "spouse", person: P(9008), spouse: { ref: P(9009) }, relType: "married", married: { year: 1990 } });
    assert.deepEqual(res.ops.map((o) => o.id), ["o1", "o2", "o3", "o4"]);
    const allIds = new Set(res.summary.flatMap((s) => s.opIds));
    assert.deepEqual([...allIds].sort(), ["o1", "o2", "o3", "o4"]);
  });

  it("base_versions lists the existing objects the ops touch, when versions are given", () => {
    const res = compile({ type: "children", person: P(9008), otherParent: { unknown: true }, children: [{ who: { ref: P(9012) } }] }, { version: (k) => (k === P(9012) ? 3 : 9) });
    assert.deepEqual(res.base_versions, { [P(9008)]: 9, [P(9012)]: 3 });
    assert.deepEqual(compileRelationship({ intent: { type: "children", person: P(9008), children: [{ who: { ref: P(9012) } }] }, get, today: TODAY }).base_versions, {});
  });

  it("the ops never mention an object outside the ones named in touched and created", () => {
    for (const sc of GOLDEN.scenarios) {
      const res = compile(sc.intent);
      const named = new Set([...res.preview.touched, ...res.preview.created]);
      assert.equal(named.size, res.stats.touched + res.stats.created, sc.id);
      for (const o of res.ops) assert.ok(o.op === "create" ? /^new:\d+$/.test(o.obj) : named.has(o.obj), `${sc.id} ${o.id}`);
    }
  });

  it("the destructive flag is only set by unlink", () => {
    for (const sc of GOLDEN.scenarios) assert.equal(compile(sc.intent).destructive, sc.intent.type === "unlink", sc.id);
  });

  it("the objects it reads are not changed", () => {
    const frozen = JSON.parse(JSON.stringify(TREE));
    for (const sc of GOLDEN.scenarios) compile(sc.intent);
    assert.deepEqual(TREE, frozen);
  });
});

describe("module hygiene", () => {
  it("imports only the EditOp engine, the Gramps semantics and the duplicate matcher, and nothing from node or the network", () => {
    const want = { "relationships.js": ["./duplicates.js", "./ops.js", "./semantics.js"], "duplicates.js": [] };
    for (const [f, imports] of Object.entries(want)) {
      const src = readFileSync(resolve(here, "../../src/records", f), "utf8");
      const found = [...src.matchAll(/^\s*import\s[^;]*?from\s+["']([^"']+)["']/gm)].map((m) => m[1]).sort();
      assert.deepEqual(found, imports, f);
      assert.ok(!/\bprocess\.|\brequire\(|\bfetch\(|node:|Date\.now|new Date/.test(src.replace(/\/\/.*$/gm, "")), `${f} touches the environment`);
    }
  });
});
